43	/**
44	 * A {@link Storage} implementation for the {@link JournalNode}.
45	 * 
46	 * The JN has a storage directory for each namespace for which it stores
47	 * metadata. There is only a single directory per JN in the current design.
48	 */
49	class JNStorage extends Storage {
50	
51	  private final FileJournalManager fjm;
52	  private final StorageDirectory sd;
53	  private StorageState state;
54	
55	  private static final List<Pattern> PAXOS_DIR_PURGE_REGEXES =
56	      ImmutableList.of(Pattern.compile("(\\d+)"));
57	
58	  private static final String STORAGE_EDITS_SYNC = "edits.sync";
59	
60	  /**
61	   * @param conf Configuration object
62	   * @param logDir the path to the directory in which data will be stored
63	   * @param errorReporter a callback to report errors
64	   * @throws IOException 
65	   */
66	  protected JNStorage(Configuration conf, File logDir, StartupOption startOpt,
67	      StorageErrorReporter errorReporter) throws IOException {
68	    super(NodeType.JOURNAL_NODE);
69	    
70	    sd = new StorageDirectory(logDir, null, false, new FsPermission(conf.get(
71	        DFSConfigKeys.DFS_JOURNAL_EDITS_DIR_PERMISSION_KEY,
72	        DFSConfigKeys.DFS_JOURNAL_EDITS_DIR_PERMISSION_DEFAULT)));
73	    this.addStorageDir(sd);
74	    this.fjm = new FileJournalManager(conf, sd, errorReporter);
75	
76	    analyzeAndRecoverStorage(startOpt);
77	  }
78	  
79	  FileJournalManager getJournalManager() {
80	    return fjm;
81	  }
82	
83	  @Override
84	  public boolean isPreUpgradableLayout(StorageDirectory sd)
85	      throws IOException {
86	    return false;
87	  }
88	
89	  /**
90	   * Find an edits file spanning the given transaction ID range.
91	   * If no such file exists, an exception is thrown.
92	   */
93	  File findFinalizedEditsFile(long startTxId, long endTxId)
94	      throws IOException {
95	    File ret = new File(sd.getCurrentDir(),
96	        NNStorage.getFinalizedEditsFileName(startTxId, endTxId));
97	    if (!ret.exists()) {
98	      throw new IOException(
99	          "No edits file for range " + startTxId + "-" + endTxId);
100	    }
101	    return ret;
102	  }
103	
104	  /**
105	   * @return the path for an in-progress edits file starting at the given
106	   * transaction ID. This does not verify existence of the file. 
107	   */
108	  File getInProgressEditLog(long startTxId) {
109	    return new File(sd.getCurrentDir(),
110	        NNStorage.getInProgressEditsFileName(startTxId));
111	  }
112	  
113	  /**
114	   * @param segmentTxId the first txid of the segment
115	   * @param epoch the epoch number of the writer which is coordinating
116	   * recovery
117	   * @return the temporary path in which an edits log should be stored
118	   * while it is being downloaded from a remote JournalNode
119	   */
120	  File getSyncLogTemporaryFile(long segmentTxId, long epoch) {
121	    String name = NNStorage.getInProgressEditsFileName(segmentTxId) +
122	        ".epoch=" + epoch; 
123	    return new File(sd.getCurrentDir(), name);
124	  }
125	
126	  File getCurrentDir() {
127	    return sd.getCurrentDir();
128	  }
129	
130	  /**
131	   * Directory {@code edits.sync} temporarily holds the log segments
132	   * downloaded through {@link JournalNodeSyncer} before they are moved to
133	   * {@code current} directory.
134	   *
135	   * @return the directory path
136	   */
137	  File getEditsSyncDir() {
138	    return new File(sd.getRoot(), STORAGE_EDITS_SYNC);
139	  }
140	
141	  File getTemporaryEditsFile(long startTxId, long endTxId) {
142	    return new File(getEditsSyncDir(), String.format("%s_%019d-%019d",
143	            NNStorage.NameNodeFile.EDITS.getName(), startTxId, endTxId));
144	  }
145	
146	  File getFinalizedEditsFile(long startTxId, long endTxId) {
147	    return new File(sd.getCurrentDir(), String.format("%s_%019d-%019d",
148	            NNStorage.NameNodeFile.EDITS.getName(), startTxId, endTxId));
149	  }
150	
151	  /**
152	   * @return the path for the file which contains persisted data for the
153	   * paxos-like recovery process for the given log segment.
154	   */
155	  File getPaxosFile(long segmentTxId) {
156	    return new File(getOrCreatePaxosDir(), String.valueOf(segmentTxId));
157	  }
158	  
159	  File getOrCreatePaxosDir() {
160	    File paxosDir = new File(sd.getCurrentDir(), "paxos");
161	    if(!paxosDir.exists()) {
162	      LOG.info("Creating paxos dir: {}", paxosDir.toPath());
163	      if(!paxosDir.mkdir()) {
164	        LOG.error("Could not create paxos dir: {}", paxosDir.toPath());
165	      }
166	    }
167	    return paxosDir;
168	  }
169	  
170	  File getRoot() {
171	    return sd.getRoot();
172	  }
173	  
174	  /**
175	   * Remove any log files and associated paxos files which are older than
176	   * the given txid.
177	   */
178	  void purgeDataOlderThan(long minTxIdToKeep) throws IOException {
179	    fjm.purgeLogsOlderThan(minTxIdToKeep);
180	
181	    purgeMatching(getOrCreatePaxosDir(),
182	        PAXOS_DIR_PURGE_REGEXES, minTxIdToKeep);
183	  }
184	  
185	  /**
186	   * Purge files in the given directory which match any of the set of patterns.
187	   * The patterns must have a single numeric capture group which determines
188	   * the associated transaction ID of the file. Only those files for which
189	   * the transaction ID is less than the <code>minTxIdToKeep</code> parameter
190	   * are removed.
191	   */
192	  private static void purgeMatching(File dir, List<Pattern> patterns,
193	      long minTxIdToKeep) throws IOException {
194	
195	    for (File f : FileUtil.listFiles(dir)) {
196	      if (!f.isFile()) continue;
197	      
198	      for (Pattern p : patterns) {
199	        Matcher matcher = p.matcher(f.getName());
200	        if (matcher.matches()) {
201	          // This parsing will always succeed since the group(1) is
202	          // /\d+/ in the regex itself.
203	          long txid = Long.parseLong(matcher.group(1));
204	          if (txid < minTxIdToKeep) {
205	            LOG.info("Purging no-longer needed file {}", txid);
206	            if (!f.delete()) {
207	              LOG.warn("Unable to delete no-longer-needed data {}", f);
208	            }
209	            break;
210	          }
211	        }
212	      }
213	    }
214	  }
215	
216	  void format(NamespaceInfo nsInfo, boolean force) throws IOException {
217	    unlockAll();
218	    try {
219	      sd.analyzeStorage(StartupOption.FORMAT, this, !force);
220	    } finally {
221	      sd.unlock();
222	    }
223	    setStorageInfo(nsInfo);
224	
225	    LOG.info("Formatting journal {} with nsid: {}", sd, getNamespaceID());
226	    // Unlock the directory before formatting, because we will
227	    // re-analyze it after format(). The analyzeStorage() call
228	    // below is reponsible for re-locking it. This is a no-op
229	    // if the storage is not currently locked.
230	    unlockAll();
231	    sd.clearDirectory();
232	    writeProperties(sd);
233	    getOrCreatePaxosDir();
234	    analyzeStorage();
235	  }
236	  
237	  void analyzeStorage() throws IOException {
238	    this.state = sd.analyzeStorage(StartupOption.REGULAR, this);
239	    refreshStorage();
240	  }
241	
242	  void refreshStorage() throws IOException {
243	    if (state == StorageState.NORMAL) {
244	      readProperties(sd);
245	    }
246	  }
247	
248	  @Override
249	  protected void setLayoutVersion(Properties props, StorageDirectory sd)
250	      throws IncorrectVersionException, InconsistentFSStateException {
251	    int lv = Integer.parseInt(getProperty(props, sd, "layoutVersion"));
252	    // For journal node, since it now does not decode but just scan through the
253	    // edits, it can handle edits with future version in most of the cases.
254	    // Thus currently we may skip the layoutVersion check here.
255	    layoutVersion = lv;
256	  }
257	
258	  void analyzeAndRecoverStorage(StartupOption startOpt) throws IOException {
259	    this.state = sd.analyzeStorage(startOpt, this);
260	    final boolean needRecover = state != StorageState.NORMAL
261	        && state != StorageState.NON_EXISTENT
262	        && state != StorageState.NOT_FORMATTED;
263	    if (state == StorageState.NORMAL && startOpt != StartupOption.ROLLBACK) {
264	      readProperties(sd);
265	    } else if (needRecover) {
266	      sd.doRecover(state);
267	    }
268	  }
269	
270	  void checkConsistentNamespace(NamespaceInfo nsInfo)
271	      throws IOException {
272	    if (nsInfo.getNamespaceID() != getNamespaceID()) {
273	      throw new IOException("Incompatible namespaceID for journal " +
274	          this.sd + ": NameNode has nsId " + nsInfo.getNamespaceID() +
275	          " but storage has nsId " + getNamespaceID());
276	    }
277	    
278	    if (!nsInfo.getClusterID().equals(getClusterID())) {
279	      throw new IOException("Incompatible clusterID for journal " +
280	          this.sd + ": NameNode has clusterId '" + nsInfo.getClusterID() +
281	          "' but storage has clusterId '" + getClusterID() + "'");
282	      
283	    }
284	  }
285	
286	  public void close() throws IOException {
287	    LOG.info("Closing journal storage for {}", sd);
288	    unlockAll();
289	  }
290	
291	  public boolean isFormatted() {
292	    return state == StorageState.NORMAL;
293	  }
294	}

