66	/**
67	 * The JournalNode is a daemon which allows namenodes using
68	 * the QuorumJournalManager to log and retrieve edits stored
69	 * remotely. It is a thin wrapper around a local edit log
70	 * directory with the addition of facilities to participate
71	 * in the quorum protocol.
72	 */
73	@InterfaceAudience.Private
74	public class JournalNode implements Tool, Configurable, JournalNodeMXBean {
75	  public static final Logger LOG = LoggerFactory.getLogger(JournalNode.class);
76	  private Configuration conf;
77	  private JournalNodeRpcServer rpcServer;
78	  private JournalNodeHttpServer httpServer;
79	  private final Map<String, Journal> journalsById = Maps.newHashMap();
80	  private final Map<String, JournalNodeSyncer> journalSyncersById = Maps
81	      .newHashMap();
82	  private ObjectName journalNodeInfoBeanName;
83	  private String httpServerURI;
84	  private final ArrayList<File> localDir = Lists.newArrayList();
85	  Tracer tracer;
86	
87	  static {
88	    HdfsConfiguration.init();
89	  }
90	  
91	  /**
92	   * When stopped, the daemon will exit with this code. 
93	   */
94	  private int resultCode = 0;
95	
96	  synchronized Journal getOrCreateJournal(String jid,
97	                                          String nameServiceId,
98	                                          StartupOption startOpt)
99	      throws IOException {
100	    QuorumJournalManager.checkJournalId(jid);
101	    
102	    Journal journal = journalsById.get(jid);
103	    if (journal == null) {
104	      File logDir = getLogDir(jid, nameServiceId);
105	      LOG.info("Initializing journal in directory " + logDir);
106	      journal = new Journal(conf, logDir, jid, startOpt, new ErrorReporter());
107	      journalsById.put(jid, journal);
108	      // Start SyncJouranl thread, if JournalNode Sync is enabled
109	      if (conf.getBoolean(
110	          DFSConfigKeys.DFS_JOURNALNODE_ENABLE_SYNC_KEY,
111	          DFSConfigKeys.DFS_JOURNALNODE_ENABLE_SYNC_DEFAULT)) {
112	        startSyncer(journal, jid, nameServiceId);
113	      }
114	    } else if (journalSyncersById.get(jid) != null &&
115	        !journalSyncersById.get(jid).isJournalSyncerStarted() &&
116	        !journalsById.get(jid).getTriedJournalSyncerStartedwithnsId() &&
117	        nameServiceId != null) {
118	      startSyncer(journal, jid, nameServiceId);
119	    }
120	
121	
122	    return journal;
123	  }
124	
125	  @VisibleForTesting
126	  public boolean getJournalSyncerStatus(String jid) {
127	    if (journalSyncersById.get(jid) != null) {
128	      return journalSyncersById.get(jid).isJournalSyncerStarted();
129	    } else {
130	      return false;
131	    }
132	  }
133	
134	  private void startSyncer(Journal journal, String jid, String nameServiceId) {
135	    JournalNodeSyncer jSyncer = journalSyncersById.get(jid);
136	    if (jSyncer == null) {
137	      jSyncer = new JournalNodeSyncer(this, journal, jid, conf, nameServiceId);
138	      journalSyncersById.put(jid, jSyncer);
139	    }
140	    jSyncer.start(nameServiceId);
141	  }
142	
143	  @VisibleForTesting
144	  public Journal getOrCreateJournal(String jid) throws IOException {
145	    return getOrCreateJournal(jid, null, StartupOption.REGULAR);
146	  }
147	
148	  public Journal getOrCreateJournal(String jid,
149	                                    String nameServiceId)
150	      throws IOException {
151	    return getOrCreateJournal(jid, nameServiceId, StartupOption.REGULAR);
152	  }
