154	  @Override
155	  public void setConf(Configuration conf) {
156	    this.conf = conf;
157	
158	    String journalNodeDir = null;
159	    Collection<String> nameserviceIds;
160	
161	    nameserviceIds = conf.getTrimmedStringCollection(
162	        DFSConfigKeys.DFS_INTERNAL_NAMESERVICES_KEY);
163	
164	    if (nameserviceIds.size() == 0) {
165	      nameserviceIds = conf.getTrimmedStringCollection(
166	          DFSConfigKeys.DFS_NAMESERVICES);
167	    }
168	
169	    //if nameservicesIds size is less than 2, it means it is not a federated
170	    // setup
171	    if (nameserviceIds.size() < 2) {
172	      // Check in HA, if journal edit dir is set by appending with
173	      // nameserviceId
174	      for (String nameService : nameserviceIds) {
175	        journalNodeDir = conf.get(DFSConfigKeys.DFS_JOURNALNODE_EDITS_DIR_KEY +
176	        "." + nameService);
177	      }
178	      if (journalNodeDir == null) {
179	        journalNodeDir = conf.get(DFSConfigKeys.DFS_JOURNALNODE_EDITS_DIR_KEY,
180	            DFSConfigKeys.DFS_JOURNALNODE_EDITS_DIR_DEFAULT);
181	      }
182	      localDir.add(new File(journalNodeDir.trim()));
183	    }
184	
185	    if (this.tracer == null) {
186	      this.tracer = new Tracer.Builder("JournalNode").
187	          conf(TraceUtils.wrapHadoopConf("journalnode.htrace", conf)).
188	          build();
189	    }
190	  }
191	
192	  private static void validateAndCreateJournalDir(File dir)
193	      throws IOException {
194	
195	    if (!dir.isAbsolute()) {
196	      throw new IllegalArgumentException(
197	          "Journal dir '" + dir + "' should be an absolute path");
198	    }
199	    DiskChecker.checkDir(dir);
200	  }
201	
202	  @Override
203	  public Configuration getConf() {
204	    return conf;
205	  }
206	
207	  @Override
208	  public int run(String[] args) throws Exception {
209	    start();
210	    return join();
211	  }
212	
213	  /**
214	   * Start listening for edits via RPC.
215	   */
216	  public void start() throws IOException {
217	    Preconditions.checkState(!isStarted(), "JN already running");
218	
219	    try {
220	
221	      for (File journalDir : localDir) {
222	        validateAndCreateJournalDir(journalDir);
223	      }
224	      DefaultMetricsSystem.initialize("JournalNode");
225	      JvmMetrics.create("JournalNode",
226	          conf.get(DFSConfigKeys.DFS_METRICS_SESSION_ID_KEY),
227	          DefaultMetricsSystem.instance());
228	
229	      InetSocketAddress socAddr = JournalNodeRpcServer.getAddress(conf);
230	      SecurityUtil.login(conf, DFSConfigKeys.DFS_JOURNALNODE_KEYTAB_FILE_KEY,
231	          DFSConfigKeys.DFS_JOURNALNODE_KERBEROS_PRINCIPAL_KEY,
232	          socAddr.getHostName());
233	
234	      registerJNMXBean();
235	
236	      httpServer = new JournalNodeHttpServer(conf, this,
237	          getHttpServerBindAddress(conf));
238	      httpServer.start();
239	
240	      httpServerURI = httpServer.getServerURI().toString();
241	
242	      rpcServer = new JournalNodeRpcServer(conf, this);
243	      rpcServer.start();
244	    } catch (IOException ioe) {
245	      //Shutdown JournalNode of JournalNodeRpcServer fails to start
246	      LOG.error("Failed to start JournalNode.", ioe);
247	      this.stop(1);
248	      throw ioe;
249	    }
250	  }
251	
252	  public boolean isStarted() {
253	    return rpcServer != null;
254	  }
255	
256	  /**
257	   * @return the address the IPC server is bound to
258	   */
259	  public InetSocketAddress getBoundIpcAddress() {
260	    return rpcServer.getAddress();
261	  }
262	
