267	  /**
268	   * Stop the daemon with the given status code
269	   * @param rc the status code with which to exit (non-zero
270	   * should indicate an error)
271	   */
272	  public void stop(int rc) {
273	    this.resultCode = rc;
274	
275	    for (JournalNodeSyncer jSyncer : journalSyncersById.values()) {
276	      jSyncer.stopSync();
277	    }
278	
279	    if (rpcServer != null) { 
280	      rpcServer.stop();
281	    }
282	
283	    if (httpServer != null) {
284	      try {
285	        httpServer.stop();
286	      } catch (IOException ioe) {
287	        LOG.warn("Unable to stop HTTP server for " + this, ioe);
288	      }
289	    }
290	    
291	    for (Journal j : journalsById.values()) {
292	      IOUtils.cleanupWithLogger(LOG, j);
293	    }
294	
295	    DefaultMetricsSystem.shutdown();
296	
297	    if (journalNodeInfoBeanName != null) {
298	      MBeans.unregister(journalNodeInfoBeanName);
299	      journalNodeInfoBeanName = null;
300	    }
301	    if (tracer != null) {
302	      tracer.close();
303	      tracer = null;
304	    }
305	  }
306	
307	  /**
308	   * Wait for the daemon to exit.
309	   * @return the result code (non-zero if error)
310	   */
311	  int join() throws InterruptedException {
312	    if (rpcServer != null) {
313	      rpcServer.join();
314	    }
315	    return resultCode;
316	  }
317	  
318	  public void stopAndJoin(int rc) throws InterruptedException {
319	    stop(rc);
320	    join();
321	  }
322	
323	  /**
324	   * Return the directory inside our configured storage
325	   * dir which corresponds to a given journal. 
326	   * @param jid the journal identifier
327	   * @return the file, which may or may not exist yet
328	   */
329	  private File getLogDir(String jid, String nameServiceId) throws IOException{
330	    String dir = null;
331	    if (nameServiceId != null) {
332	      dir = conf.get(DFSConfigKeys.DFS_JOURNALNODE_EDITS_DIR_KEY + "." +
333	          nameServiceId);
334	    }
335	    if (dir == null) {
336	      dir = conf.get(DFSConfigKeys.DFS_JOURNALNODE_EDITS_DIR_KEY,
337	          DFSConfigKeys.DFS_JOURNALNODE_EDITS_DIR_DEFAULT);
338	    }
339	
340	    File journalDir = new File(dir.trim());
341	    if (!localDir.contains(journalDir)) {
342	      //It is a federated setup, we need to validate journalDir
343	      validateAndCreateJournalDir(journalDir);
344	      localDir.add(journalDir);
345	    }
346	
347	    Preconditions.checkArgument(jid != null &&
348	        !jid.isEmpty(),
349	        "bad journal identifier: %s", jid);
350	    assert jid != null;
351	    return new File(journalDir, jid);
352	  }
