356	  @Override // JournalNodeMXBean
357	  public String getJournalsStatus() {
358	    // jid:{Formatted:True/False}
359	    Map<String, Map<String, String>> status = 
360	        new HashMap<String, Map<String, String>>();
361	    synchronized (this) {
362	      for (Map.Entry<String, Journal> entry : journalsById.entrySet()) {
363	        Map<String, String> jMap = new HashMap<String, String>();
364	        jMap.put("Formatted", Boolean.toString(entry.getValue().isFormatted()));
365	        status.put(entry.getKey(), jMap);
366	      }
367	    }
368	    
369	    // It is possible that some journals have been formatted before, while the 
370	    // corresponding journals are not in journalsById yet (because of restarting
371	    // JN, e.g.). For simplicity, let's just assume a journal is formatted if
372	    // there is a directory for it. We can also call analyzeStorage method for
373	    // these directories if necessary.
374	    // Also note that we do not need to check localDir here since
375	    // validateAndCreateJournalDir has been called before we register the
376	    // MXBean.
377	    for (File jDir : localDir) {
378	      File[] journalDirs = jDir.listFiles(new FileFilter() {
379	        @Override
380	        public boolean accept(File file) {
381	          return file.isDirectory();
382	        }
383	      });
384	
385	      if (journalDirs != null) {
386	        for (File journalDir : journalDirs) {
387	          String jid = journalDir.getName();
388	          if (!status.containsKey(jid)) {
389	            Map<String, String> jMap = new HashMap<String, String>();
390	            jMap.put("Formatted", "true");
391	            status.put(jid, jMap);
392	          }
393	        }
394	      }
395	    }
396	
397	    return JSON.toString(status);
398	  }
