public static class Builder {
  private String baseDir;
  private int numJournalNodes = 3;
  private boolean format = true;
  private final Configuration conf;
  private int[] httpPorts;
  private int[] rpcPorts;

  static {
    DefaultMetricsSystem.setMiniClusterMode(true);
  }

  public Builder(Configuration conf) {
    this.conf = conf;
  }

  public Builder baseDir(String d) {
    this.baseDir = d;
    return this;
  }

  public Builder numJournalNodes(int n) {
    this.numJournalNodes = n;
    return this;
  }

  public Builder format(boolean f) {
    this.format = f;
    return this;
  }

  /**
   * Set the http ports for JournalNodes.
   *
   * @param ports http ports
   * @return this builder for call chaining
   */
  public Builder httpPorts(int[] ports) {
    this.httpPorts = ports;
    return this;
  }

  /**
   * Set the rpc ports for JournalNodes.
   *
   * @param ports rpc ports
   * @return this builder for call chaining
   */
  public Builder rpcPorts(int[] ports) {
    this.rpcPorts = ports;
    return this;
  }

  public MiniJournalCluster build() throws IOException {
    return new MiniJournalCluster(this);
  }
}

