  @Test
  public void testSetHttpAndRpcPorts() throws IOException {
    Configuration conf = new Configuration();
    final int numJns = 2;
    int[] rpcPorts = new int[numJns];
    int[] httpPorts = new int[numJns];
    for (int i = 0; i < numJns; i++) {
      rpcPorts[i] = ServerSocketUtil.getPort(20000 + 10 * i, 10);
      httpPorts[i] = ServerSocketUtil.getPort(21000 + 10 * i, 10);
    }
    MiniJournalCluster c = new MiniJournalCluster.Builder(conf)
        .numJournalNodes(numJns)
        .rpcPorts(rpcPorts)
        .httpPorts(httpPorts)
        .build();
    c.waitActive();
    try {
      for (int i = 0; i < numJns; i++) {
        JournalNode node = c.getJournalNode(i);
        assertEquals(rpcPorts[i], node.getBoundIpcAddress().getPort());
        assertEquals(httpPorts[i], node.getBoundHttpAddress().getPort());
      }
    } finally {
      c.shutdown();
    }
  }
